def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.C = pyo.Set(initialize=range(1, d["num_centers"] + 1))
    model.S = pyo.Set(initialize=range(1, d["num_stores"] + 1))
    model.CS = pyo.Set(
        initialize=[(c, s) for c in range(1, d["num_centers"] + 1)
                    for s in range(1, d["num_stores"] + 1)]
    )

    # Binary open/close decisions for distribution centers
    model.y = pyo.Var(model.C, within=pyo.Binary)

    # Units shipped from center c to store s
    model.x = pyo.Var(model.CS, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return (
            sum(d["open_cost"][c] * m.y[c] for c in m.C)
            + sum(d["transport_cost"][c][s] * m.x[c, s] for c in m.C for s in m.S)
        )
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each store's demand must be met
    def demand_rule(m, s):
        return sum(m.x[c, s] for c in m.C) >= d["demand"][s]
    model.demand_link = pyo.Constraint(model.S, rule=demand_rule)

    # Capacity of each center, and no shipping from a closed center (big-M)
    def capacity_rule(m, c):
        return sum(m.x[c, s] for s in m.S) <= d["capacity"][c] * m.y[c]
    model.capacity_link = pyo.Constraint(model.C, rule=capacity_rule)

    return model


